\$ErrorActionPreference='Continue'
\$exe = 'D:\Develop\STM32CubeCLT\STLink-gdb-server\bin\ST-LINK_gdbserver.exe'
\$cp  = 'D:\Develop\STM32CubeCLT\STM32CubeProgrammer\bin'
Write-Host '=== Probe ST-LINK_gdbserver (10s timeout) ==='
\$p = Start-Process -FilePath \$exe -ArgumentList @('-p','50000','-cp',\$cp,'--swd','--attach','--halt') -NoNewWindow -PassThru -RedirectStandardOutput '\$env:TEMP\stlink_gs_out.txt' -RedirectStandardError '\$env:TEMP\stlink_gs_err.txt'
Start-Sleep -Seconds 4
if (-not \$p.HasExited) {
  Write-Host 'STATUS: RUNNING (good) pid=' \$p.Id
  Stop-Process -Id \$p.Id -Force
  Write-Host 'Stopped test server.'
} else {
  Write-Host 'STATUS: EXITED early code=' \$p.ExitCode
}
Write-Host '--- stdout ---'
if (Test-Path \$env:TEMP\stlink_gs_out.txt) { Get-Content \$env:TEMP\stlink_gs_out.txt }
Write-Host '--- stderr ---'
if (Test-Path \$env:TEMP\stlink_gs_err.txt) { Get-Content \$env:TEMP\stlink_gs_err.txt }
" 2>&1

