$out = Join-Path $env:TEMP "stlink_gs_out.txt"
$err = Join-Path $env:TEMP "stlink_gs_err.txt"
if (Test-Path $out) { Remove-Item $out -Force }
if (Test-Path $err) { Remove-Item $err -Force }
Write-Host "=== Probe ST-LINK_gdbserver ==="
$p = Start-Process -FilePath $exe -ArgumentList @("-p","50000","-cp",$cp,"--swd","--attach","--halt") -NoNewWindow -PassThru -RedirectStandardOutput $out -RedirectStandardError $err
Start-Sleep -Seconds 5
if ($null -eq $p) { Write-Host "failed to start"; exit 1 }
if (-not $p.HasExited) {
