  Write-Host "Stopped test server."
} else {
  Write-Host "STATUS: EXITED early code=$($p.ExitCode)"
}
Write-Host "--- stdout ---"
if (Test-Path $out) { Get-Content $out -Raw }
Write-Host "--- stderr ---"
if (Test-Path $err) { Get-Content $err -Raw }
' 2>&1

export TRELLIS_CONTEXT_ID='opencode_ses_0abacc3b3ffemelo7MqNKHQ0EZ'; powershell.exe -NoProfile -Command '
$ErrorActionPreference = "Continue"
$exe = "D:\Develop\STM32CubeCLT\STLink-gdb-server\bin\ST-LINK_gdbserver.exe"
$cp  = "D:\Develop\STM32CubeCLT\STM32CubeProgrammer\bin"
$out = Join-Path $env:TEMP "stlink_gs_out.txt"
$err = Join-Path $env:TEMP "stlink_gs_err.txt"

function Probe($label, $args) {
  Write-Host "===== $label ====="
  if (Test-Path $out) { Remove-Item $out -Force }
  if (Test-Path $err) { Remove-Item $err -Force }
  $p = Start-Process -FilePath $exe -ArgumentList $args -NoNewWindow -PassThru -RedirectStandardOutput $out -RedirectStandardError $err
  Start-Sleep -Seconds 4
  if ($null -ne $p -and -not $p.HasExited) {
    Write-Host "STATUS: RUNNING pid=$($p.Id)"
    Stop-Process -Id $p.Id -Force -ErrorAction SilentlyContinue
  } else {
    Write-Host "STATUS: EXITED"
  }
  if (Test-Path $out) { Get-Content $out }
  if (Test-Path $err) { Get-Content $err }
  Write-Host ""
}

# Help first
& $exe -h 2>&1 | Select-Object -First 120
' 2>&1
